solution:
const validator = {
  set(target, prop, value) {
    if (prop === "age") {
      if (typeof value !== "number" || value < 0) {
        return false
      }
    }
    target[prop] = value
    return true
  }
}
const person = new Proxy({ name: "Hariom" }, validator)
person.age = 25
person.age = -5
return { name: person.name, age: person.age }
